{
  "cases": [
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"t1\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 5}, {\"op\": \"reserve\", \"tenant\": \"t2\", \"key\": \"k1\", \"sku\": \"sensor\", \"qty\": 5}, {\"op\": \"stock\", \"tenant\": \"t1\", \"sku\": \"widget\"}, {\"op\": \"stock\", \"tenant\": \"t2\", \"sku\": \"sensor\"}]",
      "family": "tenant_isolation",
      "name": "cross tenant cross sku stock isolation"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"atlas\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 10}, {\"op\": \"reserve\", \"tenant\": \"atlas\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 10}, {\"op\": \"release\", \"tenant\": \"atlas\", \"key\": \"k1\"}, {\"op\": \"reserve\", \"tenant\": \"atlas\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 10}, {\"op\": \"reserve\", \"tenant\": \"atlas\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 10}, {\"op\": \"stock\", \"tenant\": \"atlas\", \"sku\": \"widget\"}]",
      "family": "idempotency",
      "name": "post release double idempotent retry"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"alpha\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 1}, {\"op\": \"release\", \"tenant\": \"alpha\", \"key\": \"k1\"}, {\"op\": \"release\", \"tenant\": \"alpha\", \"key\": \"k1\"}, {\"op\": \"stock\", \"tenant\": \"alpha\", \"sku\": \"widget\"}]",
      "family": "idempotency",
      "name": "single release idempotency stock check"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"beta\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 5}, {\"op\": \"reserve\", \"tenant\": \"beta\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 6}, {\"op\": \"stock\", \"tenant\": \"beta\", \"sku\": \"widget\"}]",
      "family": "payload_binding",
      "name": "conflict preserves original stock"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"gamma\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 5}, {\"op\": \"reserve\", \"tenant\": \"gamma\", \"key\": \"k1\", \"sku\": \"sensor\", \"qty\": 5}, {\"op\": \"stock\", \"tenant\": \"gamma\", \"sku\": \"widget\"}, {\"op\": \"stock\", \"tenant\": \"gamma\", \"sku\": \"sensor\"}]",
      "family": "payload_binding",
      "name": "sku conflict does not alter other sku stock"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"delta\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 11}]",
      "family": "validation",
      "name": "quantity exactly at max limit valid"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"epsilon\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": -1}]",
      "family": "validation",
      "name": "negative quantity invalid no state change"
    },
    {
      "actions_json": "[{\"op\": \"reserve\", \"tenant\": \"zeta\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 3}, {\"op\": \"reserve\", \"tenant\": \"zeta\", \"key\": \"k1\", \"sku\": \"widget\", \"qty\": 8}, {\"op\": \"stock\", \"tenant\": \"zeta\", \"sku\": \"widget\"}]",
      "family": "inventory",
      "name": "insufficient after partial consumption"
    }
  ]
,
  "rationale": "The previous suite failed to detect silent state corruption in tenant isolation (cross-tenant stock leakage) and idempotency (double consumption on retry). This new suite introduces: 1) Cross-tenant/cross-sku isolation checks to ensure keys don't bleed inventory across tenants or SKUs. 2) Post-release idempotency verification with stock assertions to confirm retries don't consume extra stock. 3) Explicit validation of boundary quantities (max valid, negative) to catch input sanitization failures that lead to state mutations. 4) Payload binding tests that verify conflict responses do not silently update stock levels."
}
